#include <functional>
#include <chrono>
#include <thread>
#include <stdexcept>
#include <algorithm>
#include <random>

struct RetryConfig {
    int max_retries = 3;
    std::chrono::milliseconds base_delay{100};
    std::chrono::milliseconds max_delay{30000};
    double multiplier = 2.0;
    double jitter_factor = 0.1; // 0.0 = no jitter, 1.0 = full jitter
};

template <typename F, typename... Args>
auto retry_with_backoff(const RetryConfig& config, F&& func, Args&&... args)
    -> decltype(func(std::forward<Args>(args)...))
{
    if (config.max_retries < 0) {
        throw std::invalid_argument("max_retries must be non-negative");
    }
    if (config.base_delay.count() < 0) {
        throw std::invalid_argument("base_delay must be non-negative");
    }
    if (config.multiplier < 1.0) {
        throw std::invalid_argument("multiplier must be >= 1.0");
    }

    std::mt19937 rng(std::random_device{}());
    std::uniform_real_distribution<double> jitter_dist(0.0, 1.0);

    std::exception_ptr last_exception;

    for (int attempt = 0; attempt <= config.max_retries; ++attempt) {
        try {
            return func(std::forward<Args>(args)...);
        } catch (...) {
            last_exception = std::current_exception();

            if (attempt == config.max_retries) {
                break; // exhausted retries
            }

            // Calculate delay with exponential backoff
            double delay_ms = static_cast<double>(config.base_delay.count())
                              * std::pow(config.multiplier, attempt);

            // Clamp to max_delay
            delay_ms = std::min(delay_ms, static_cast<double>(config.max_delay.count()));

            // Apply jitter to avoid thundering herd
            if (config.jitter_factor > 0.0) {
                double jitter = delay_ms * config.jitter_factor * jitter_dist(rng);
                delay_ms += jitter;
            }

            // Guard against overflow / negative values
            auto sleep_ms = std::chrono::milliseconds(
                static_cast<long long>(std::max(0.0, delay_ms))
            );

            std::this_thread::sleep_for(sleep_ms);
        }
    }

    std::rethrow_exception(last_exception);
}
```

Usage:

```cpp
// Simple case
auto result = retry_with_backoff(RetryConfig{}, []() {
    return make_http_request("/api/data");
});

// Custom config
RetryConfig cfg{
    .max_retries = 5,
    .base_delay = std::chrono::milliseconds{200},
    .max_delay = std::chrono::milliseconds{60000},
    .multiplier = 2.0,
    .jitter_factor = 0.25
};

auto data = retry_with_backoff(cfg, fetch_data, url, timeout);
```

Edge cases handled:

- **Overflow** — `pow` can blow up; clamped by `max_delay` and `std::max(0.0, ...)`
- **Thundering herd** — jitter randomizes delays so retrying clients don't all hit at once
- **Zero retries** — executes exactly once, rethrows on failure
- **Invalid config** — rejects negative retries, negative delays, multiplier < 1
- **Void return type** — works fine since the template deduces `void` and `return func(...)` is valid for void functions in C++
- **Exception preservation** — always rethrows the *last* exception, not a wrapper

The jitter is additive (not full-random) by default — keeps backoff predictable while still spreading load. Bump `jitter_factor` to 1.0 if you want AWS-style "full jitter."

# Adapter Pattern

The Adapter pattern converts the interface of one class into another interface that clients expect. It lets incompatible classes work together.

**When to use:** You have existing code with one interface, but need it to conform to a different interface — without modifying the original.

## Practical Example

Scenario: Your system works with a `ModernPrinter` interface, but you need to integrate a legacy `OldPrinter` class that has a different API.

```cpp
#include <iostream>
#include <string>

// The interface your system expects
class ModernPrinter {
public:
    virtual ~ModernPrinter() = default;
    virtual void printDocument(const std::string& text) = 0;
    virtual void printImage(const std::string& filename) = 0;
};

// Legacy class you can't modify. Different method names, different signatures.
class OldPrinter {
public:
    void printText(const char* text, int length) {
        std::cout << "[OldPrinter] Printing text (" << length << " chars): " << text << "\n";
    }

    void printBitmap(const char* path) {
        std::cout << "[OldPrinter] Printing bitmap: " << path << "\n";
    }
};

// The Adapter: wraps OldPrinter, exposes ModernPrinter interface
class PrinterAdapter : public ModernPrinter {
public:
    explicit PrinterAdapter(OldPrinter* legacyPrinter)
        : legacy_(legacyPrinter) {}

    void printDocument(const std::string& text) override {
        // Translate the modern call into the legacy call
        legacy_->printText(text.c_str(), static_cast<int>(text.size()));
    }

    void printImage(const std::string& filename) override {
        legacy_->printBitmap(filename.c_str());
    }

private:
    OldPrinter* legacy_;
};

// Client code — only knows about ModernPrinter
void processJob(ModernPrinter& printer) {
    printer.printDocument("Quarterly Report Q4 2025");
    printer.printImage("/img/chart.bmp");
}

int main() {
    OldPrinter oldDevice;
    PrinterAdapter adapter(&oldDevice);

    processJob(adapter); // works seamlessly
}
```

**Output:**
```
[OldPrinter] Printing text (24 chars): Quarterly Report Q4 2025
[OldPrinter] Printing bitmap: /img/chart.bmp
```

## Key points

- `OldPrinter` is untouched — no modifications to legacy code.
- `PrinterAdapter` does the translation between interfaces.
- Client code (`processJob`) is decoupled from the legacy implementation entirely.
- If you later swap `OldPrinter` for something else, only the adapter changes.

## Object vs. Class Adapter

What's shown above is an **object adapter** (composition — holds a pointer to the adaptee). There's also a **class adapter** that uses multiple inheritance:

```cpp
class PrinterClassAdapter : public ModernPrinter, private OldPrinter {
public:
    void printDocument(const std::string& text) override {
        printText(text.c_str(), static_cast<int>(text.size()));
    }

    void printImage(const std::string& filename) override {
        printBitmap(filename.c_str());
    }
};
```

Object adapter is generally preferred in C++ — it's more flexible (can adapt subclasses of `OldPrinter` too) and avoids tight coupling through inheritance.

Here's a practical test suite for a natural language text tokenizer. I'll assume a reasonable tokenizer interface and cover the cases that actually matter.

```python
import pytest
from tokenizer import tokenize  # adjust import to your module


class TestBasicTokenization:
    """Core splitting behavior."""

    def test_simple_sentence(self):
        assert tokenize("The cat sat on the mat") == ["The", "cat", "sat", "on", "the", "mat"]

    def test_empty_string(self):
        assert tokenize("") == []

    def test_single_word(self):
        assert tokenize("hello") == ["hello"]

    def test_multiple_spaces(self):
        assert tokenize("hello   world") == ["hello", "world"]

    def test_leading_trailing_whitespace(self):
        assert tokenize("  hello world  ") == ["hello", "world"]

    def test_tabs_and_newlines(self):
        assert tokenize("hello\tworld\nfoo") == ["hello", "world", "foo"]


class TestPunctuation:
    """Punctuation should be split from words (standard NLP behavior)."""

    def test_period_at_end(self):
        result = tokenize("Hello world.")
        assert "world" in result or "world." in result  # depends on design
        # Strict version:
        assert result == ["Hello", "world", "."]

    def test_comma_separation(self):
        assert tokenize("yes, no") == ["yes", ",", "no"]

    def test_question_mark(self):
        assert tokenize("Why?") == ["Why", "?"]

    def test_exclamation(self):
        assert tokenize("Stop!") == ["Stop", "!"]

    def test_multiple_punctuation(self):
        assert tokenize("Wait...") == ["Wait", "..."]

    def test_quotes(self):
        result = tokenize('"Hello," she said.')
        assert result == ['"', "Hello", ",", '"', "she", "said", "."]

    def test_parentheses(self):
        result = tokenize("foo (bar) baz")
        assert result == ["foo", "(", "bar", ")", "baz"]

    def test_semicolon_and_colon(self):
        result = tokenize("item: value; next")
        assert result == ["item", ":", "value", ";", "next"]


class TestContractions:
    """English contractions — a classic tokenizer headache."""

    def test_simple_contraction(self):
        result = tokenize("I'm happy")
        # Common approaches: ["I", "'m", "happy"] or ["I'm", "happy"]
        assert result in [["I", "'m", "happy"], ["I'm", "happy"]]

    def test_not_contraction(self):
        result = tokenize("don't")
        assert result in [["do", "n't"], ["don't"], ["don", "'t"]]

    def test_would_contraction(self):
        result = tokenize("she'd go")
        assert result[0] in ["she'd", "she"]

    def test_possessive(self):
        result = tokenize("John's book")
        assert result in [["John", "'s", "book"], ["John's", "book"]]


class TestSpecialTokens:
    """Numbers, URLs, emails, and other non-word tokens."""

    def test_numbers(self):
        assert tokenize("I have 3 cats") == ["I", "have", "3", "cats"]

    def test_decimal_numbers(self):
        result = tokenize("costs 3.50 dollars")
        assert "3.50" in result  # should not split on decimal point

    def test_negative_numbers(self):
        result = tokenize("it was -5 degrees")
        assert "-5" in result or ("-" in result and "5" in result)

    def test_url(self):
        result = tokenize("visit https://example.com today")
        assert "https://example.com" in result

    def test_email(self):
        result = tokenize("mail me at user@example.com please")
        assert "user@example.com" in result

    def test_hashtag(self):
        result = tokenize("trending #python today")
        assert "#python" in result or "python" in result

    def test_mention(self):
        result = tokenize("ask @john about it")
        assert "@john" in result or "john" in result

    def test_currency(self):
        result = tokenize("costs $50")
        assert "$50" in result or ("$" in result and "50" in result)


class TestHyphenation:
    """Hyphenated words and dashes."""

    def test_hyphenated_word(self):
        result = tokenize("well-known fact")
        assert result in [["well-known", "fact"], ["well", "-", "known", "fact"]]

    def test_em_dash(self):
        result = tokenize("foo—bar")
        assert result == ["foo", "—", "bar"]

    def test_en_dash_range(self):
        result = tokenize("pages 1–5")
        assert "1–5" in result or "1" in result


class TestUnicode:
    """Non-ASCII and multilingual input."""

    def test_accented_characters(self):
        assert tokenize("café résumé") == ["café", "résumé"]

    def test_cyrillic(self):
        assert tokenize("Привет мир") == ["Привет", "мир"]

    def test_mixed_scripts(self):
        result = tokenize("hello мир world")
        assert result == ["hello", "мир", "world"]

    def test_emoji(self):
        result = tokenize("I love 🐍 python")
        assert "🐍" in result

    def test_cjk_characters(self):
        # CJK often needs character-level tokenization
        result = tokenize("我喜欢猫")
        assert len(result) >= 1  # at minimum, not empty


class TestEdgeCases:
    """Things that break naive implementations."""

    def test_only_whitespace(self):
        assert tokenize("   \t\n  ") == []

    def test_only_punctuation(self):
        result = tokenize("...")
        assert result == ["..."] or result == [".", ".", "."]

    def test_very_long_word(self):
        word = "a" * 10000
        result = tokenize(word)
        assert result == [word]

    def test_repeated_punctuation_and_spaces(self):
        result = tokenize("  !!  ?? ")
        assert len(result) > 0

    def test_null_bytes(self):
        # Should handle gracefully, not crash
        result = tokenize("hello\x00world")
        assert isinstance(result, list)

    def test_mixed_line_endings(self):
        result = tokenize("a\r\nb\rc\nd")
        assert result == ["a", "b", "c", "d"]


class TestReturnType:
    """Contract checks."""

    def test_returns_list(self):
        assert isinstance(tokenize("hello"), list)

    def test_all_elements_are_strings(self):
        result = tokenize("Hello, world! 123")
        assert all(isinstance(t, str) for t in result)

    def test_no_empty_tokens(self):
        result = tokenize("hello   world  ,  foo")
        assert "" not in result
        assert all(len(t) > 0 for t in result)
```

Key design decisions in this suite:

- **Punctuation splitting** — most NLP tokenizers separate punctuation from words. If yours doesn't, adjust the `TestPunctuation` assertions.
- **Contractions** — I used `assert result in [...]` for cases where multiple valid designs exist. Pin it down once you decide your tokenizer's behavior.
- **URLs/emails** — a good tokenizer keeps these intact. If yours is simpler (just whitespace split), drop these or mark them `xfail`.
- **Unicode** — if you're processing real-world text, these aren't optional.

Run with `pytest -v` and adjust assertions to match your tokenizer's actual contract. The tests document behavior — once they pass, they lock it in.
